#!/usr/bin/env python3\n\"\"\"\nTeste Rápido - Link Perfil no Sidebar\n======================================\n\nVerifica se o link do perfil foi adicionado corretamente no sidebar.\n\"\"\"\n\ndef test_perfil_in_sidebar():\n    \"\"\"Testa se o perfil foi adicionado no sidebar\"\"\"\n    print(\"🔍 VERIFICANDO LINK PERFIL NO SIDEBAR:\")\n    print(\"-\" * 40)\n    \n    try:\n        with open('components/sidebar.py', 'r', encoding='utf-8') as f:\n            sidebar_content = f.read()\n        \n        checks = [\n            ('\"Perfil\"', 'Label do link'),\n            ('\"/perfil\"', 'URL do link'),\n            ('\"tabler:user\"', 'Ícone do link'),\n            ('\"sidebar-nav-perfil\"', 'ID do link'),\n            ('elif pathname == \"/perfil\":', 'Callback de ativação')\n        ]\n        \n        all_ok = True\n        for check, description in checks:\n            if check in sidebar_content:\n                print(f\"✅ {description}\")\n            else:\n                print(f\"❌ {description} - FALTANDO\")\n                all_ok = False\n        \n        return all_ok\n        \n    except Exception as e:\n        print(f\"❌ Erro ao verificar sidebar: {e}\")\n        return False\n\ndef main():\n    \"\"\"Executa verificação\"\"\"\n    print(\"🚀 TESTE DO LINK PERFIL NO SIDEBAR\")\n    print(\"=\" * 50)\n    \n    success = test_perfil_in_sidebar()\n    \n    print(\"\\n\" + \"=\" * 50)\n    if success:\n        print(\"✅ LINK PERFIL ADICIONADO COM SUCESSO!\")\n        print(\"\\n🎯 Agora você pode:\")\n        print(\"   1. Executar: python app.py\")\n        print(\"   2. Ver o link 'Perfil' na seção 'Outros' do sidebar\")\n        print(\"   3. Clicar no link para acessar /perfil\")\n        print(\"   4. Testar todas as funcionalidades da página\")\n    else:\n        print(\"❌ PROBLEMAS ENCONTRADOS\")\n        print(\"   Verifique os erros listados acima\")\n    \n    print(\"=\" * 50)\n    return success\n\nif __name__ == \"__main__\":\n    import sys\n    success = main()\n    sys.exit(0 if success else 1)\n